ALTER TABLE public.profiles ADD COLUMN first_name text NOT NULL DEFAULT '', ADD COLUMN last_name text NOT NULL DEFAULT '', ADD COLUMN preferred_team_name text NOT NULL DEFAULT '';
ALTER TABLE public.leagues ADD COLUMN invitations_enabled boolean NOT NULL DEFAULT true, ADD COLUMN pickups_enabled boolean NOT NULL DEFAULT true, ADD COLUMN swaps_enabled boolean NOT NULL DEFAULT true, ADD COLUMN season_start date;
CREATE TABLE public.league_matchups(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), league_id uuid NOT NULL REFERENCES public.leagues(id), week_no int NOT NULL, week_start date NOT NULL, home_team_id uuid NOT NULL REFERENCES public.teams(id), away_team_id uuid REFERENCES public.teams(id), UNIQUE(league_id,week_no,home_team_id));
GRANT SELECT ON public.league_matchups TO anon,authenticated; GRANT ALL ON public.league_matchups TO service_role;
ALTER TABLE public.league_matchups ENABLE ROW LEVEL SECURITY;
CREATE POLICY matchup_read ON public.league_matchups FOR SELECT USING(public.can_read_league(league_id));
CREATE FUNCTION public.configure_league_controls(lid uuid,capacity int,invitations boolean,pickups boolean,swaps boolean,start_date date DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE l leagues; n int; BEGIN IF NOT public.league_commissioner(lid) THEN RAISE EXCEPTION 'Only the commissioner can edit settings'; END IF; SELECT * INTO l FROM leagues WHERE id=lid FOR UPDATE; SELECT count(*) INTO n FROM teams WHERE league_id=lid; IF capacity NOT BETWEEN 2 AND 8 OR capacity<n THEN RAISE EXCEPTION 'Capacity must be 2–8 and cannot be below the current team count'; END IF; IF l.draft_status<>'waiting' AND (capacity<>l.max_teams OR start_date IS DISTINCT FROM l.season_start) THEN RAISE EXCEPTION 'Capacity and season start are fixed after the draft starts'; END IF; IF start_date IS NOT NULL AND extract(isodow FROM start_date)<>1 THEN RAISE EXCEPTION 'Season weeks must start on a Monday'; END IF; UPDATE leagues SET max_teams=capacity,invitations_enabled=invitations,pickups_enabled=pickups,swaps_enabled=swaps,season_start=start_date WHERE id=lid; END $$;
CREATE FUNCTION public.enforce_league_controls() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE l leagues; BEGIN SELECT * INTO l FROM leagues WHERE id=NEW.league_id FOR UPDATE; IF l.is_demo OR auth.uid() IS NULL THEN RETURN NEW; END IF; IF TG_TABLE_NAME='teams' THEN IF NOT l.invitations_enabled THEN RAISE EXCEPTION 'Invitations are paused by the commissioner'; END IF; ELSE IF l.draft_status='complete' THEN IF NEW.player_id IS DISTINCT FROM OLD.player_id THEN IF NEW.player_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM roster_slots WHERE team_id=NEW.team_id AND player_id=NEW.player_id) AND NOT l.pickups_enabled THEN RAISE EXCEPTION 'Player pickups are paused by the commissioner'; END IF; IF NOT l.swaps_enabled AND (NEW.player_id IS NULL OR EXISTS(SELECT 1 FROM roster_slots WHERE team_id=NEW.team_id AND player_id=NEW.player_id)) THEN RAISE EXCEPTION 'Lineup swaps are paused by the commissioner'; END IF; END IF; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER enforce_invitation_controls BEFORE INSERT ON public.teams FOR EACH ROW EXECUTE FUNCTION public.enforce_league_controls();
CREATE TRIGGER enforce_roster_controls BEFORE UPDATE ON public.roster_slots FOR EACH ROW EXECUTE FUNCTION public.enforce_league_controls();
CREATE FUNCTION public.build_league_schedule(lid uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE ids uuid[];n int;r int;i int;last_id uuid;start_day date; BEGIN IF EXISTS(SELECT 1 FROM league_matchups WHERE league_id=lid) THEN RETURN; END IF; SELECT array_agg(id ORDER BY draft_order) INTO ids FROM teams WHERE league_id=lid; n:=coalesce(array_length(ids,1),0); IF n<2 THEN RETURN; END IF; IF n%2=1 THEN ids:=array_append(ids,NULL::uuid);n:=n+1; END IF; SELECT coalesce(season_start,date_trunc('week',now())::date) INTO start_day FROM leagues WHERE id=lid; FOR r IN 1..n-1 LOOP FOR i IN 1..n/2 LOOP IF ids[i] IS NULL THEN INSERT INTO league_matchups(league_id,week_no,week_start,home_team_id) VALUES(lid,r,start_day+(r-1)*7,ids[n+1-i]); ELSE INSERT INTO league_matchups(league_id,week_no,week_start,home_team_id,away_team_id) VALUES(lid,r,start_day+(r-1)*7,ids[i],ids[n+1-i]); END IF; END LOOP; last_id:=ids[n]; FOR i IN REVERSE n..3 LOOP ids[i]:=ids[i-1]; END LOOP; ids[2]:=last_id; END LOOP; END $$;
CREATE FUNCTION public.schedule_after_draft() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.draft_status='complete' AND OLD.draft_status<>'complete' THEN PERFORM public.build_league_schedule(NEW.id); END IF; RETURN NEW; END $$;
CREATE TRIGGER schedule_draft_completed AFTER UPDATE ON public.leagues FOR EACH ROW EXECUTE FUNCTION public.schedule_after_draft();
CREATE OR REPLACE FUNCTION public.finalize_fantasy_week(lid uuid,week_start date) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE l leagues;t teams;p numeric;m league_matchups;hp numeric;ap numeric; BEGIN IF NOT public.league_commissioner(lid) THEN RAISE EXCEPTION 'Only the commissioner can finalize a week'; END IF; SELECT * INTO l FROM leagues WHERE id=lid FOR UPDATE; IF l.draft_status<>'complete' THEN RAISE EXCEPTION 'Finish the draft first'; END IF; PERFORM public.build_league_schedule(lid); IF NOT EXISTS(SELECT 1 FROM league_matchups lm WHERE lm.league_id=lid AND lm.week_start=finalize_fantasy_week.week_start) THEN RAISE EXCEPTION 'Choose a week from the league schedule'; END IF; IF EXISTS(SELECT 1 FROM weekly_results wr WHERE wr.league_id=lid AND wr.week_start=finalize_fantasy_week.week_start) THEN RAISE EXCEPTION 'This week was already finalized'; END IF; IF NOT EXISTS(SELECT 1 FROM game_boxscores WHERE league_id=lid AND game_date>=week_start AND game_date<week_start+7) THEN RAISE EXCEPTION 'Record game box scores for this week first'; END IF; FOR t IN SELECT * FROM teams WHERE league_id=lid LOOP SELECT coalesce(sum(b.pts*(l.scoring->>'pts')::numeric+b.reb*(l.scoring->>'reb')::numeric+b.ast*(l.scoring->>'ast')::numeric+b.stl*(l.scoring->>'stl')::numeric+b.blk*(l.scoring->>'blk')::numeric+b.turnovers*(l.scoring->>'turnovers')::numeric),0) INTO p FROM roster_slots rs JOIN game_boxscores b ON b.player_id=rs.player_id AND b.league_id=lid WHERE rs.team_id=t.id AND rs.slot<=3 AND b.game_date>=week_start AND b.game_date<week_start+7; INSERT INTO weekly_results(league_id,team_id,week_start,points) VALUES(lid,t.id,week_start,p); UPDATE teams SET total_points=total_points+p WHERE id=t.id; END LOOP; FOR m IN SELECT * FROM league_matchups lm WHERE lm.league_id=lid AND lm.week_start=finalize_fantasy_week.week_start AND lm.away_team_id IS NOT NULL LOOP SELECT points INTO hp FROM weekly_results wr WHERE wr.team_id=m.home_team_id AND wr.week_start=finalize_fantasy_week.week_start; SELECT points INTO ap FROM weekly_results wr WHERE wr.team_id=m.away_team_id AND wr.week_start=finalize_fantasy_week.week_start; UPDATE teams SET wins=wins+(hp>ap)::int,losses=losses+(hp<ap)::int,ties=ties+(hp=ap)::int WHERE id=m.home_team_id; UPDATE teams SET wins=wins+(ap>hp)::int,losses=losses+(ap<hp)::int,ties=ties+(ap=hp)::int WHERE id=m.away_team_id; END LOOP; INSERT INTO league_activity(league_id,message) VALUES(lid,'Weekly matchup finalized for '||week_start::text); END $$;
REVOKE ALL ON FUNCTION public.configure_league_controls(uuid,int,boolean,boolean,boolean,date),public.build_league_schedule(uuid),public.schedule_after_draft(),public.enforce_league_controls() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.configure_league_controls(uuid,int,boolean,boolean,boolean,date) TO authenticated;